<?php
namespace App\Services;
use App\Enums\FinancialTransactionStatus; use App\Enums\FinancialTransactionType; use App\Models\{AdvertisingInvoice,AdvertisingPayment,FinancialTransaction}; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
class AdvertisingBillingService {
 public function recalculate(AdvertisingInvoice $invoice): AdvertisingInvoice { $subtotal=(int)$invoice->items()->sum('line_total_cents'); $total=max(0,$subtotal-(int)$invoice->discount_cents+(int)$invoice->tax_cents); $paid=(int)$invoice->payments()->where('type','payment')->where('status','succeeded')->sum('amount_cents'); $refunded=(int)$invoice->payments()->where('type','refund')->where('status','succeeded')->sum('amount_cents'); $netPaid=max(0,$paid-$refunded); $balance=max(0,$total-$netPaid); $status=$invoice->status; if(!in_array($status,['draft','void'],true)){ $status=$balance===0&&$total>0?($refunded>=$paid&&$paid>0?'refunded':'paid'):($netPaid>0?'partially_paid':'issued'); if($status==='issued'&&$invoice->due_at?->isPast())$status='overdue'; } $invoice->update(['subtotal_cents'=>$subtotal,'total_cents'=>$total,'paid_cents'=>$paid,'refunded_cents'=>$refunded,'balance_cents'=>$balance,'status'=>$status,'paid_at'=>$status==='paid'?($invoice->paid_at?:now()):null]); return $invoice->refresh(); }
 public function record(AdvertisingInvoice $invoice,int $amount,string $provider='manual',?string $reference=null,?string $notes=null,string $type='payment'): AdvertisingPayment { if($invoice->status==='void')throw ValidationException::withMessages(['invoice'=>'Void invoices cannot accept payments.']); $invoice=$this->recalculate($invoice); $max=$type==='refund'?$invoice->paid_cents-$invoice->refunded_cents:$invoice->balance_cents; if($amount<1||$amount>$max)throw ValidationException::withMessages(['amount_cents'=>'Amount exceeds the available invoice balance.']); return DB::transaction(function()use($invoice,$amount,$provider,$reference,$notes,$type){$p=AdvertisingPayment::create(['uuid'=>(string)Str::uuid(),'advertising_invoice_id'=>$invoice->id,'type'=>$type,'status'=>'succeeded','provider'=>$provider,'amount_cents'=>$amount,'currency'=>$invoice->currency,'provider_reference'=>$reference,'notes'=>$notes,'processed_at'=>now()]); FinancialTransaction::create(['advertising_invoice_id'=>$invoice->id,'advertising_payment_id'=>$p->id,'type'=>$type==='refund'?FinancialTransactionType::Refund:FinancialTransactionType::Payment,'status'=>FinancialTransactionStatus::Succeeded,'amount_cents'=>$amount,'currency'=>$invoice->currency,'provider'=>$provider,'provider_reference'=>$reference,'reason'=>'Advertising invoice '.$type,'occurred_at'=>now()]); $this->recalculate($invoice); return $p;}); }
}
